1: import * as React from "react"
2: import { ChevronLeft, ChevronRight, ChevronDown } from "lucide-react"
3: import { 
4:   format, 
5:   addMonths, 
6:   subMonths, 
7:   startOfMonth, 
8:   endOfMonth, 
9:   startOfWeek, 
10:   endOfWeek, 
11:   isSameMonth, 
12:   isSameDay, 
13:   addDays, 
14:   eachDayOfInterval,
15:   isToday
16: } from "date-fns"
17: import { es } from "date-fns/locale"
18: import { useLanguage } from "../../context/LanguageContext"
19: 
20: import { cn } from "../../lib/utils"
21: 
22: export interface CalendarProps {
23:   selected?: Date
24:   onSelect?: (date: Date) => void
25:   className?: string
26: }
27: 
28: export function Calendar({ selected, onSelect, className }: CalendarProps) {
29:   const { language } = useLanguage()
30:   const [currentMonth, setCurrentMonth] = React.useState(selected || new Date())
31:   const [showMonthDropdown, setShowMonthDropdown] = React.useState(false)
32:   const [showYearDropdown, setShowYearDropdown] = React.useState(false)
33:   const containerRef = React.useRef<HTMLDivElement>(null)
34: 
35:   React.useEffect(() => {
36:     if (selected) {
37:       setCurrentMonth(selected)
38:     }
39:   }, [selected])
40: 
41:   React.useEffect(() => {
42:     const handleClickOutside = (event: MouseEvent) => {
43:       if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
44:         setShowMonthDropdown(false);
45:         setShowYearDropdown(false);
46:       }
47:     };
48:     document.addEventListener("mousedown", handleClickOutside);
49:     return () => document.removeEventListener("mousedown", handleClickOutside);
50:   }, []);
51: 
52:   const nextMonth = () => setCurrentMonth(addMonths(currentMonth, 1))
53:   const prevMonth = () => setCurrentMonth(subMonths(currentMonth, 1))
54: 
55:   const monthStart = startOfMonth(currentMonth)
56:   const monthEnd = endOfMonth(monthStart)
57:   const startDate = startOfWeek(monthStart)
58:   const endDate = endOfWeek(monthEnd)
59: 
60:   const calendarDays = eachDayOfInterval({
61:     start: startDate,
62:     end: endDate,
63:   })
64: 
65:   const rows: Date[][] = []
66:   let days: Date[] = []
67: 
68:   calendarDays.forEach((day, i) => {
69:     days.push(day)
70:     if ((i + 1) % 7 === 0) {
71:       rows.push(days)
72:       days = []
73:     }
74:   })
75: 
76:   const handleSelectToday = () => {
77:     const today = new Date();
78:     setCurrentMonth(today);
79:     onSelect?.(today);
80:   };
81: 
82:   const handleSelectYesterday = () => {
83:     const yesterday = new Date();
84:     yesterday.setDate(yesterday.getDate() - 1);
85:     setCurrentMonth(yesterday);
86:     onSelect?.(yesterday);
87:   };
88: 
89:   return (
90:     <div ref={containerRef} className={cn("p-1 bg-transparent select-none relative w-full", className)}>
91:       {/* Quick Date Presets */}
92:       <div className="flex items-center justify-center gap-1.5 mb-3">
93:         <button
94:           type="button"
95:           onClick={handleSelectToday}
96:           className="px-3 py-1 rounded-xl text-[10px] font-bold uppercase tracking-wider bg-secondary/80 hover:bg-secondary text-muted-foreground hover:text-foreground transition-colors cursor-pointer border border-border/50"
97:         >
98:           {language === 'es' ? 'Hoy' : 'Today'}
99:         </button>
100:         <button
101:           type="button"
102:           onClick={handleSelectYesterday}
103:           className="px-3 py-1 rounded-xl text-[10px] font-bold uppercase tracking-wider bg-secondary/80 hover:bg-secondary text-muted-foreground hover:text-foreground transition-colors cursor-pointer border border-border/50"
104:         >
105:           {language === 'es' ? 'Ayer' : 'Yesterday'}
106:         </button>
107:       </div>
108: 
109:       {/* Month & Year Navigation Header */}
110:       <div className="flex items-center justify-between mb-3 px-1">
111:         <div className="flex items-center gap-1.5">
112:           {/* Custom Month Select */}
113:           <div className="relative">
114:             <button
115:               type="button"
116:               onClick={() => {
117:                 setShowMonthDropdown(!showMonthDropdown);
118:                 setShowYearDropdown(false);
119:               }}
120:               className="h-8 px-2.5 rounded-xl border border-border/80 bg-secondary/70 text-xs font-bold text-foreground flex items-center gap-1 hover:bg-secondary transition-colors cursor-pointer"
121:             >
122:               <span className="capitalize">{format(currentMonth, "MMMM", { locale: language === 'es' ? es : undefined })}</span>
123:               <ChevronDown size={13} className="text-muted-foreground shrink-0" />
124:             </button>
125:             {showMonthDropdown && (
126:               <div className="absolute top-full left-0 mt-1 w-32 max-h-48 overflow-y-auto bg-card/95 border border-border/80 rounded-2xl shadow-xl z-50 py-1.5 backdrop-blur-xl flex flex-col gap-0.5 custom-scrollbar">
127:                 {Array.from({ length: 12 }, (_, i) => {
128:                   const date = new Date(2024, i, 1);
129:                   const name = format(date, "MMMM", { locale: language === 'es' ? es : undefined });
130:                   return (
131:                     <button
132:                       key={i}
133:                       type="button"
134:                       onClick={() => {
135:                         const next = new Date(currentMonth);
136:                         next.setMonth(i);
137:                         setCurrentMonth(next);
138:                         setShowMonthDropdown(false);
139:                       }}
140:                       className={cn(
141:                         "w-full text-left px-3 py-1.5 text-xs font-semibold hover:bg-secondary transition-colors cursor-pointer capitalize",
142:                         currentMonth.getMonth() === i ? "text-primary bg-primary/10 font-bold" : "text-foreground"
143:                       )}
144:                     >
145:                       {name}
146:                     </button>
147:                   );
148:                 })}
149:               </div>
150:             )}
151:           </div>
152: 
153:           {/* Custom Year Select */}
154:           <div className="relative">
155:             <button
156:               type="button"
157:               onClick={() => {
158:                 setShowYearDropdown(!showYearDropdown);
159:                 setShowMonthDropdown(false);
160:               }}
161:               className="h-8 px-2.5 rounded-xl border border-border/80 bg-secondary/70 text-xs font-bold text-foreground flex items-center gap-1 hover:bg-secondary transition-colors cursor-pointer"
162:             >
163:               {format(currentMonth, "yyyy")}
164:               <ChevronDown size={13} className="text-muted-foreground shrink-0" />
165:             </button>
166:             {showYearDropdown && (
167:               <div className="absolute top-full left-0 mt-1 w-24 max-h-48 overflow-y-auto bg-card/95 border border-border/80 rounded-2xl shadow-xl z-50 py-1.5 backdrop-blur-xl flex flex-col gap-0.5 custom-scrollbar">
168:                 {Array.from({ length: 120 }, (_, i) => {
169:                   const year = new Date().getFullYear() - i;
170:                   return (
171:                     <button
172:                       key={year}
173:                       type="button"
174:                       onClick={() => {
175:                         const next = new Date(currentMonth);
176:                         next.setFullYear(year);
177:                         setCurrentMonth(next);
178:                         setShowYearDropdown(false);
179:                       }}
180:                       className={cn(
181:                         "w-full text-left px-3 py-1.5 text-xs font-semibold hover:bg-secondary transition-colors cursor-pointer",
182:                         currentMonth.getFullYear() === year ? "text-primary bg-primary/10 font-bold" : "text-foreground"
183:                       )}
184:                     >
185:                       {year}
186:                     </button>
187:                   );
188:                 })}
189:               </div>
190:             )}
191:           </div>
192:         </div>
193: 
194:         {/* Prev / Next Month arrows */}
195:         <div className="flex items-center gap-1">
196:           <button
197:             type="button"
198:             onClick={prevMonth}
199:             className="size-8 rounded-xl flex items-center justify-center hover:bg-secondary text-muted-foreground hover:text-foreground transition-colors cursor-pointer border border-transparent hover:border-border/60"
200:             title="Previous month"
201:           >
202:             <ChevronLeft size={16} strokeWidth={2.5} />
203:           </button>
204:           <button
205:             type="button"
206:             onClick={nextMonth}
207:             className="size-8 rounded-xl flex items-center justify-center hover:bg-secondary text-muted-foreground hover:text-foreground transition-colors cursor-pointer border border-transparent hover:border-border/60"
208:             title="Next month"
209:           >
210:             <ChevronRight size={16} strokeWidth={2.5} />
211:           </button>
212:         </div>
213:       </div>
214:       
215:       {/* Days of Week Header */}
216:       <div className="grid grid-cols-7 mb-1.5">
217:         {(language === 'es' ? ["Do", "Lu", "Ma", "Mi", "Ju", "Vi", "Sa"] : ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"]).map((day) => (
218:           <div key={day} className="text-center text-[10px] font-bold text-muted-foreground/70 uppercase tracking-widest py-1">
219:             {day}
220:           </div>
221:         ))}
222:       </div>
223: 
224:       {/* Days Grid */}
225:       <div className="space-y-1">
226:         {rows.map((row, i) => (
227:           <div key={i} className="grid grid-cols-7 gap-1">
228:             {row.map((day) => {
229:               const isSelected = selected && isSameDay(day, selected)
230:               const isCurrentMonth = isSameMonth(day, monthStart)
231:               const isTodayDay = isToday(day)
232: 
233:               return (
234:                 <button
235:                   type="button"
236:                   key={day.toString()}
237:                   onClick={() => onSelect?.(day)}
238:                   className={cn(
239:                     "h-8 w-full text-xs font-semibold rounded-xl transition-all relative flex items-center justify-center cursor-pointer",
240:                     !isCurrentMonth && "text-muted-foreground/30 pointer-events-none",
241:                     isCurrentMonth && !isSelected && "text-foreground hover:bg-secondary hover:text-primary",
242:                     isSelected && "bg-primary text-primary-foreground font-bold shadow-md shadow-primary/25 hover:bg-primary/90",
243:                     isTodayDay && !isSelected && "text-primary font-bold border border-primary/30"
244:                   )}
245:                 >
246:                   {format(day, "d")}
247:                   {isTodayDay && !isSelected && (
248:                     <div className="absolute bottom-1 size-1 rounded-full bg-primary" />
249:                   )}
250:                 </button>
251:               )
252:             })}
253:           </div>
254:         ))}
255:       </div>
256:     </div>
257:   )
258: }
